let url,
  youtube = $("#youtube").DataTable({
    responsive: true,
    scrollX: true,
    ajax: readUrl,
    columnDefs: [
      {
        searcable: false,
        orderable: false,
        targets: 0,
      },
    ],
    order: [[1, "asc"]],
    columns: [
      {
        data: "no",
      },
      {
        data: null,
        render: function (data, type, row, meta) {
          return (
            '<a href="https://www.youtube.com/watch?v=' +
            data["alamat"] +
            '" width=100>' +
            '<img src="http://img.youtube.com/vi/' +
            data["alamat"] +
            '/hqdefault.jpg" width=150 title="YouTube Video" alt="YouTube Video" />' +
            "</a>"
          );
        },
      },
      {
        data: "descripsi",
      },
      {
        data: null,
        title: "Foto Tampil Di android",
        render: function (data, type, row, meta) {
          return (
            '<img src="' +
            data["id_siswa"] +
            '" width=100><br>alamat foto di Android ' +
            data["id_siswa"]
          );
        },
      },
      {
        data: null,
        title: "Action",
        render: function (data, type, row, meta) {
          return (
            '<button class="btn btn-sm btn-success" onclick="edit(' +
            data["no"] +
            ')">Edit</button> <button class="btn btn-sm btn-danger" onclick="remove(' +
            data["no"] +
            ')">Delete</button>'
          );
        },
      },
    ],
  });

function reloadTable() {
  youtube.reloadTable;
  youtube.ajax.reload();
}

function addData() {
  $.ajax({
    url: addUrl,
    type: "post",
    dataType: "json",
    data: $("#form").serialize(),
    success: (a) => {
      $(".modal").modal("hide");
      Swal.fire("Sukses", "Sukses Menambahkan Data", "success"), reloadTable();
    },
    error: (a) => {
      console.log(a);
    },
  });
}

function remove(e) {
  swal({
    title: "Hapus Data ?",
    text: "yakin data ini akan di hapus",
    icon: "warning",
    buttons: ["No", "Yes"],
    dangerMode: true,
  }).then(function (isConfirm) {
    if (isConfirm) {
      $.ajax({
        url: deleteUrl,
        type: "post",
        dataType: "json",
        data: {
          no: e,
        },
        success: () => {
          //alert("Data Berhasil Di hapus");
          Swal.fire("Sukses", "Sukses Menghapus Data", "success"),
            reloadTable();
        },
        error: function () {
          alert("Error occured");
        },
      });
    } else {
      swal("Cancelled", "File tidak jadi dihapus", "error");
    }
  });
}

function editData() {
  $.ajax({
    url: editUrl,
    type: "post",
    dataType: "json",
    data: $("#form").serialize(),
    success: () => {
      $(".modal").modal("hide"),
        Swal.fire("Sukses", "Sukses Mengedit Data", "success"),
        reloadTable();
    },
    error: (a) => {
      console.log(a);
    },
  });
}

function add() {
  (url = "add"),
    $('[name="id_siswa"]').val("http://img.youtube.com/vi/_isi_/hqdefault.jpg"),
    $(".modal-title").html("Add Data"),
    $('.modal button[type="submit"]').html("Add");
}
function rubahalamat() {
  var alamat =
    "http://img.youtube.com/vi/" +
    $('[name="alamat"]').val() +
    "/hqdefault.jpg";
  $('[name="id_siswa"]').val(alamat);
}
function edit(a) {
  $.ajax({
    url: getYoutubeUrl,
    type: "get",
    dataType: "json",
    data: {
      no: a,
    },
    success: (a) => {
      $('[name="no"]').val(a.no),
        $('[name="alamat"]').val(a.alamat),
        $('[name="descripsi"]').val(a.descripsi),
        $('[name="id_siswa"]').val(a.id_siswa),
        $(".modal").modal("show"),
        $(".modal-title").html("Edit Data"),
        $('.modal button[type="submit"]').html("Edit"),
        (url = "edit");
    },
    error: (a) => {
      console.log(a);
    },
  });
}

youtube.on("order.dt search.dt", () => {
  youtube
    .column(0, {
      search: "applied",
      order: "applied",
    })
    .nodes()
    .each((a, e) => {
      a.innerHTML = e + 1;
    });
}),
  $("#form").validate({
    errorElement: "span",
    errorPlacement: (a, e) => {
      a.addClass("invalid-feedback"), e.closest(".form-group").append(a);
    },
    submitHandler: () => {
      "edit" == url ? editData() : addData();
    },
  }),
  $(".modal").on("hidden.bs.modal", () => {
    $("#form")[0].reset(), $("#form").validate().resetForm();
  });
